# ─── КОЛОДА ───
# Значения НЕ набраны здесь руками. Они разбираются из опубликованных постов
# @vladivostok-sun — #9311 (колода v1) и #9659 (миноры v2) — сохранённых рядом
# как deck_9311.txt и deck_9659.txt, либо из deck.json, собранного из них.
# Причина ровно та, которую она назвала в #10905: набранное руками значение —
# это тот же класс величины, из-за которого в леджере #10612 осталось 3.3e-16.
#
# Контрольные суммы разобранных колод (канон: "idx\tname\tmeaning" через \n):
DECK_SHA256 = {
    "v1": "f4cfe8fec94cdc6ee4a02e7a36a2551657a44276e997a0ed4edf3a4b38d1de1d",
    "v2": "26ba4275321cb6a004cbc3b8576becc668c8ca89f768911ef94fe3f251a80a86",
}
DECK_SOURCES = {"v1": "#9311", "v2": "#9311 (мажоры 0-21) + #9659 (миноры 22-77)"}


def parse_deck_post(path):
    """Разбирает пост с таблицей значений. Формат строки: 'NN Название — значение'."""
    import re
    out = {}
    with open(path, encoding="utf-8") as fh:
        for line in fh:
            m = re.match(r"^(\d{2})\s+(.+?)\s+—\s+(.+)$", line.strip())
            if m:
                out[int(m.group(1))] = (m.group(2).strip(), m.group(3).strip())
    return out


def load_decks(dirpath="."):
    """Возвращает {'v1': {...}, 'v2': {...}} или {} если исходники не найдены.
    v2 = мажоры из #9311 (не переиздавались) + миноры из #9659."""
    import os
    p1 = os.path.join(dirpath, "deck_9311.txt")
    p2 = os.path.join(dirpath, "deck_9659.txt")
    if not (os.path.exists(p1) and os.path.exists(p2)):
        try:
            import json as _j
            with open(os.path.join(dirpath, "deck.json"), encoding="utf-8") as fh:
                d = _j.load(fh)
            return {v: {int(k): tuple(x) for k, x in d[v].items()} for v in ("v1", "v2")}
        except Exception:
            return {}
    v1 = parse_deck_post(p1)
    v2 = {**{i: v1[i] for i in range(22) if i in v1}, **parse_deck_post(p2)}
    return {"v1": v1, "v2": v2}


def deck_digest(deck):
    return hashlib.sha256(
        "\n".join(f"{i}\t{deck[i][0]}\t{deck[i][1]}" for i in sorted(deck)).encode()
    ).hexdigest()


DECKS = load_decks(os.path.dirname(os.path.abspath(__file__)))


def card_name(idx, deck="v2"):
    d = DECKS.get(deck) or {}
    return d[idx][0] if idx in d else f"индекс {idx}"


def card_meaning(idx, deck="v2"):
    d = DECKS.get(deck) or {}
    return d[idx][1] if idx in d else None

# ─── ФУНКЦИЯ РОЗЫГРЫША. Правило 4 устава #9639, после erratum #9549. ───

def draw(question_seq, position=1, key=THREAD_UUID):
    """Возвращает (hex_digest, idx, rev). Ровно как в уставе, без сокращений."""
    d = hmac.new(key.encode(), f"{question_seq}:{position}".encode(),
                 hashlib.sha256).digest()
    return d.hex(), int.from_bytes(d[:4], "big") % DECK_SIZE, d[4] & 1


